/// `(name, docstring)` of the functions of the module.
pub(crate) const FUNCTIONS: &[(&str, &str)] = &[
    ("_cell_reduce", "Cell (containing values of a function's free variables) reducer."),
    ("_class_reduce", "Select the reducer depending on the dynamic nature of the class obj."),
    ("_code_reduce", "code object reducer."),
    ("_dynamic_class_reduce", "Save a class that can't be referenced as a module attribute.\n\n    This method is used to serialize classes that are defined inside\n    functions, or that otherwise can't be serialized as attribute lookups\n    from importable modules.\n    "),
    ("_extract_class_dict", "Retrieve a copy of the dict of a class without the inherited method."),
    ("_extract_code_globals", "Find all globals names read or written to by codeblock co."),
    ("_file_reduce", "Save a file."),
    ("_find_imported_submodules", "Find currently imported submodules used by a function.\n\n    Submodules used by a function need to be detected and referenced for the\n    function to work correctly at depickling time. Because submodules can be\n    referenced as attribute of their parent package (``package.submodule``), we\n    need a special introspection technique that does not rely on GLOBAL-related\n    opcodes to find references of them in a code object.\n\n    Example:\n    ```\n    import concurrent.futures\n    import cloudpickle\n    def func():\n        x = concurrent.futures.ThreadPoolExecutor\n    if __name__ == '__main__':\n        cloudpickle.dumps(func)\n    ```\n    The globals extracted by cloudpickle in the function's state include the\n    concurrent package, but not its submodule (here, concurrent.futures), which\n    is the module used by func. Find_imported_submodules will detect the usage\n    of concurrent.futures. Saving this module alongside with func will ensure\n    that calling func once depickled does not fail due to concurrent.futures\n    not being imported\n    "),
    ("_function_setstate", "Update the state of a dynamic function.\n\n    As __closure__ and __globals__ are readonly attributes of a function, we\n    cannot rely on the native setstate routine of pickle.load_build, that calls\n    setattr on items of the slotstate. Instead, we have to modify them inplace.\n    "),
    ("_make_skeleton_class", "Build dynamic class with an empty __dict__ to be filled once memoized\n\n    If class_tracker_id is not None, try to lookup an existing class definition\n    matching that id. If none is found, track a newly reconstructed class\n    definition under that id so that other instances stemming from the same\n    class id will also reuse this class definition.\n\n    The \"extra\" variable is meant to be a dict (or None) that can be used for\n    forward compatibility shall the need arise.\n    "),
    ("_make_skeleton_enum", "Build dynamic enum with an empty __dict__ to be filled once memoized\n\n    The creation of the enum class is inspired by the code of\n    EnumMeta._create_.\n\n    If class_tracker_id is not None, try to lookup an existing enum definition\n    matching that id. If none is found, track a newly reconstructed enum\n    definition under that id so that other instances stemming from the same\n    class id will also reuse this enum definition.\n\n    The \"extra\" variable is meant to be a dict (or None) that can be used for\n    forward compatibility shall the need arise.\n    "),
    ("_should_pickle_by_reference", "Test whether an function or a class should be pickled by reference\n\n    Pickling by reference means by that the object (typically a function or a\n    class) is an attribute of a module that is assumed to be importable in the\n    target Python environment. Loading will therefore rely on importing the\n    module and then calling `getattr` on it to access the function or class.\n\n    Pickling by reference is the only option to pickle functions and classes\n    in the standard library. In cloudpickle the alternative option is to\n    pickle by value (for instance for interactively or locally defined\n    functions and classes or for attributes of modules that have been\n    explicitly registered to be pickled by value.\n    "),
    ("_walk_global_ops", "Yield referenced name for global-referencing instructions in code."),
    ("_whichmodule", "Find the module an object belongs to.\n\n    This function differs from ``pickle.whichmodule`` in two ways:\n    - it does not mangle the cases where obj's module is __main__ and obj was\n      not found in any module.\n    - Errors arising during module introspection are ignored, as those errors\n      are considered unwanted side effects.\n    "),
    ("dump", "Serialize obj as bytes streamed into file\n\n    protocol defaults to cloudpickle.DEFAULT_PROTOCOL which is an alias to\n    pickle.HIGHEST_PROTOCOL. This setting favors maximum communication\n    speed between processes running the same Python version.\n\n    Set protocol=pickle.DEFAULT_PROTOCOL instead if you need to ensure\n    compatibility with older versions of Python (although this is not always\n    guaranteed to work because cloudpickle relies on some internal\n    implementation details that can change from one Python version to the\n    next).\n    "),
    ("dumps", "Serialize obj as a string of bytes allocated in memory\n\n    protocol defaults to cloudpickle.DEFAULT_PROTOCOL which is an alias to\n    pickle.HIGHEST_PROTOCOL. This setting favors maximum communication\n    speed between processes running the same Python version.\n\n    Set protocol=pickle.DEFAULT_PROTOCOL instead if you need to ensure\n    compatibility with older versions of Python (although this is not always\n    guaranteed to work because cloudpickle relies on some internal\n    implementation details that can change from one Python version to the\n    next).\n    "),
    ("instance", "Create a new instance of a class.\n\n    Parameters\n    ----------\n    cls : type\n        The class to create an instance of.\n\n    Returns\n    -------\n    instance : cls\n        A new instance of ``cls``.\n    "),
    ("is_tornado_coroutine", "Return whether `func` is a Tornado coroutine function.\n\n    Running coroutines are not supported.\n    "),
    ("register_pickle_by_value", "Register a module to make its functions and classes picklable by value.\n\n    By default, functions and classes that are attributes of an importable\n    module are to be pickled by reference, that is relying on re-importing\n    the attribute from the module at load time.\n\n    If `register_pickle_by_value(module)` is called, all its functions and\n    classes are subsequently to be pickled by value, meaning that they can\n    be loaded in Python processes where the module is not importable.\n\n    This is especially useful when developing a module in a distributed\n    execution environment: restarting the client Python process with the new\n    source code is enough: there is no need to re-install the new version\n    of the module on all the worker nodes nor to restart the workers.\n\n    Note: this feature is considered experimental. See the cloudpickle\n    README.md file for more details and limitations.\n    "),
    ("unregister_pickle_by_value", "Unregister that the input module should be pickled by value."),
];

/// `(name, docstring)` of the methods of `Pickler` (both implementations).
pub(crate) const PICKLER_METHODS: &[(&str, &str)] = &[
    ("_dynamic_function_reduce", "Reduce a function that is not pickleable via attribute lookup."),
    ("_function_reduce", "Reducer for function objects.\n\n        If obj is a top-level attribute of a file-backed module, this reducer\n        returns NotImplemented, making the cloudpickle.Pickler fall back to\n        traditional pickle.Pickler routines to save obj. Otherwise, it reduces\n        obj using a custom cloudpickle reducer designed specifically to handle\n        dynamic functions.\n        "),
    ("reducer_override", "Type-agnostic reducing callback for function and classes.\n\n            For performance reasons, subclasses of the C `pickle.Pickler` class\n            cannot register custom reducers for functions and classes in the\n            dispatch_table attribute. Reducers for such types must instead\n            implemented via the special `reducer_override` method.\n\n            Note that this method will be called for any object except a few\n            builtin-types (int, lists, dicts etc.), which differs from reducers\n            in the Pickler's dispatch_table, each of them being invoked for\n            objects of a specific type only.\n\n            This property comes in handy for classes: although most classes are\n            instances of the ``type`` metaclass, some of them can be instances\n            of other custom metaclasses (such as enum.EnumMeta for example). In\n            particular, the metaclass will likely not be known in advance, and\n            thus cannot be special-cased using an entry in the dispatch_table.\n            reducer_override, among other things, allows us to register a\n            reducer that will be called for any class, independently of its\n            type.\n\n            Notes:\n\n            * reducer_override has the priority over dispatch_table-registered\n            reducers.\n            * reducer_override can be used to fix other limitations of\n              cloudpickle for other types that suffered from type-specific\n              reducers, such as Exceptions. See\n              https://github.com/cloudpipe/cloudpickle/issues/248\n            "),
    ("save_function", "Registered with the dispatch to handle all function types.\n\n            Determines what kind of function obj is (e.g. lambda, defined at\n            interactive prompt, etc) and handles the pickling appropriately.\n            "),
    ("save_global", "Main dispatch method.\n\n            The name of this method is somewhat misleading: all types get\n            dispatched here.\n            "),
    ("save_pypy_builtin_func", "Save pypy equivalent of builtin functions.\n\n            PyPy does not have the concept of builtin-functions. Instead,\n            builtin-functions are simple function instances, but with a\n            builtin-code attribute.\n            Most of the time, builtin functions should be pickled by attribute.\n            But PyPy has flaky support for __qualname__, so some builtin\n            functions such as float.__new__ will be classified as dynamic. For\n            this reason only, we created this special routine. Because\n            builtin-functions are not expected to have closure or globals,\n            there is no additional hack (compared the one already implemented\n            in pickle) to protect ourselves from reference cycles. A simple\n            (reconstructor, newargs, obj.__dict__) tuple is save_reduced.  Note\n            also that PyPy improved their support for __qualname__ in v3.6, so\n            this routing should be removed when cloudpickle supports only PyPy\n            3.6 and later.\n            "),
];
